class Solution {
public:
    int minDifference(vector<int>& nums) {
        int n = nums.size();
        if (n <= 4) return 0;
        nth_element(nums.begin(), nums.begin() + 3, nums.end());
        int small[4];
        for (int i = 0; i < 4; i++) small[i] = nums[i];
        sort(small, small + 4);
        nth_element(nums.begin(), nums.end() - 4, nums.end());
        int large[4];
        for (int i = 0; i < 4; i++) large[i] = nums[n - 4 + i];
        sort(large, large + 4);
        int ans = INT_MAX;
        for (int i = 0; i < 4; i++) ans = min(ans, large[i] - small[i]);
        return ans;
    }
};
